import java.util.LinkedHashMap;
import java.util.Map;
import net.schniedelsmp.smp.util.IdLookup;
public final class IdLookupOracle { public static void main(String[] args) { String same = new String("same"); Map<String,String> shared = new LinkedHashMap<>(); shared.put("abc-111",same); shared.put("abc-222",same); require(IdLookup.uniquePrefix(shared,"abc",2)==null,"two keys sharing one value reference are ambiguous"); Map<String,String> equal = new LinkedHashMap<>(); equal.put("abc-111",new String("same")); equal.put("abc-222",new String("same")); require(IdLookup.uniquePrefix(equal,"abc",2)==null,"two keys with equal values are ambiguous"); require("same".equals(IdLookup.uniquePrefix(shared,"abc-111",2)),"exact key keeps priority"); Map<String,String> one = Map.of("abc-111","only"); require("only".equals(IdLookup.uniquePrefix(one,"abc",2)),"one matching key returns its value"); System.out.println("PASS S1 independent key-count ambiguity contract"); } private static void require(boolean ok,String message){ if(!ok) throw new AssertionError(message); } }
